handle = func(origin){
    println("origin=", origin)
    origins = str.ReplaceAll(origin, "\r\n", "|")
    println(origins)
    lines := origin.Split("\n")
    parts := origins.Split("||")
    headers := parts[0]
    cookie = getCookie(headers)
    body_data := parts[1]
    req_host = getHost(headers)

    println("Cookie 行:", cookie)
    println("请求体数据:", body_data)

    l1 := lines[0].Trim()
    l1a := l1.Split(" ")
    req_type := l1a[0].Trim() //GET
    req_path := l1a[1].Trim() ///login.php

    //l2 := lines[1].Trim()
    //l2a := l2.Split(" ")
    //req_host := l2a[1].Trim().Replace("\r", "").Replace("\n", "") //pay.bi



    if isHttps(req_host) {
        println(req_host, "是 HTTPS")
        req_host = "https://" + req_host + req_path
    } else {
        println(req_host, "不是 HTTPS")
        req_host = "http://" + req_host + req_path
    }

    str = ""
    if req_type == "GET"{
        str := "sqlmap -u "+'"'+req_host+'"'+" --batch --level=3 --random-agent --threads=8 --fresh-queries --skip-heuristics --no-cast --tamper=space2comment --cookie="+'"'+cookie+'"'
        print("\n\n\n\n\n")
        println(str)
        print("\n\n\n\n\n")
    }else if(req_type == "POST"){
        //body_data = body_data.Replace('"','\"')
        str := "sqlmap -u "+'"'+req_host+'"'+" --batch --level=3 --random-agent --threads=8 --fresh-queries --skip-heuristics --no-cast --tamper=space2comment --cookie="+'"'+cookie+'"'+" --data="+'"'+body_data+'"'
        print("\n\n\n\n\n")
        println(str)
        print("\n\n\n\n\n")
    }else{
        str := "未识别到请求类型"
        println("str=",str)
    }
    return "请到console里复制结果"
}

getHost = func(headers) {
    lines := str.Split(headers, "|")
    for line in lines {
        lineLower := str.ToLower(line)
        if str.Contains(lineLower, "host:") {
            return str.TrimSpace(str.SplitN(line, ":", 2)[1])
        }
    }
    return ""
}


getCookie = func(headers) {
    lines := str.Split(headers, "|")
    for line in lines {
        lineLower := str.ToLower(line)
        if str.Contains(lineLower, "cookie:") {
            return str.TrimSpace(str.SplitN(line, ":", 2)[1])
        }
    }
    return ""
}

isHttps = func(host) {
    host = str.TrimSpace(host)
    if host == "" {
        println("host 为空")
        return false
    }
    reqRaw := "GET / HTTP/1.1\r\nHost: " + host + "\r\nUser-Agent: yaklang\r\n\r\n"
    //println("reqRaw =", reqRaw)
    rsp, req, err := poc.HTTP(reqRaw, poc.https(true))
    //println("rsp =", rsp)
    //println("err =", err)
    if err != nil {
        //println("连接失败，错误：", err)
        return false
    }
    if rsp != nil && len(rsp) > 0 {
        //println("有响应，判定：是 HTTPS")
        return true
    }
    //println("无响应，判定：不是 HTTPS")
    return false
}
